                selectedEl.classList.add('selected');
            }
        }

        function checkAnswer() {
            const q = questions[currentQuestion];
            const userAnswer = selectedOptions[currentQuestion];
            const correct = q.correct === userAnswer;

            const feedback = document.getElementById(`feedback${currentQuestion}`);
            if (correct) {
                feedback.className = 'feedback show correct';
                feedback.textContent = 'Correto!';
                score++;
            } else {
                feedback.className = 'feedback show wrong';
                feedback.textContent = `Incorreto. A resposta correta é: ${q.correct}`;
            }

            // Marca as opções
            document.querySelectorAll('.option').forEach((el, i) => {
                const optLetter = el.querySelector('.letter').textContent;
                if (optLetter === q.correct) {
                    el.classList.add('correct');
                }
                if (optLetter === userAnswer) {
                    el.classList.add('wrong');
                }
            });

            updateProgress();
        }

        function updateProgress() {
            const progressFill = document.getElementById('progressFill');
            const percent = ((currentQuestion + 1) / questions.length) * 100;
            progressFill.style.width = `${percent}%`;
            document.getElementById('currentQ').textContent = currentQuestion + 1;
        }

        // Event listener para botão de submeter
        function submitAnswer() {
            checkAnswer();
            currentQuestion++;

            if (currentQuestion < questions.length) {
                renderQuestion();
            } else {
                showResult();
            }
        }

        // Adiciona listener ao botão
        document.querySelector('.btn-group').innerHTML = `
            <button class="btn-submit" onclick="submitAnswer()">Submeter Respostas</button>
            <button class="btn-reset" onclick="resetQuiz()">Reiniciar</button>
        `;

        function showResult() {
            document.getElementById('quiz').style.display = 'none';
            document.getElementById('resultContainer').classList.add('show');

            document.getElementById('finalScore').textContent = score;
            document.getElementById('correctCount').textContent = score;
            document.getElementById('totalQuestions').textContent = questions.length;

            const percentage = Math.round((score / questions.length) * 100);
            document.querySelector('.result-detail').innerHTML = 
                `Sua nota: ${score}/20 (${percentage}%) - ${Math.round(percentage)}%`;
        }

        function resetQuiz() {
            currentQuestion = 0;
            selectedOptions = {};
            score = 0;
            document.getElementById('resultContainer').classList.remove('show');
            document.getElementById('quiz').style.display = 'block';
            renderQuestion();
        }
    </script>
</body>
</html>
```

## Como funciona o simulado:

### 📋 Estrutura
